public static class RequestScope
{
    private static readonly AsyncLocal<RequestContext?> Current = new();

    public static IDisposable Begin(RequestContext ctx) => new Scope(ctx);
    public static string? RequestId => Current.Value?.RequestId;

    private sealed class Scope : IDisposable
    {
        public Scope(RequestContext ctx) => Current.Value = ctx;
        public void Dispose() => Current.Value = null;
    }
}
